from pathlib import Path
import sys,json
import pandas as pd
import numpy as np
ROOT=Path(__file__).resolve().parents[2]; sys.path.append(str(ROOT))
from src.common.utils import *
CFG=load_config(); BRONZE=ROOT/CFG['bronze_path']; SILVER=ROOT/CFG['silver_path']; Q=ROOT/CFG['quarantine_path']; GOLD=ROOT/CFG['gold_path']; REPORT=ROOT/CFG['report_path']; META=ROOT/CFG['metadata_path']
RAW={'plants':'data/raw/master/plants.csv','lines':'data/raw/master/lines.csv','machines':'data/raw/master/machines.csv','products':'data/raw/master/products.csv','suppliers':'data/raw/master/suppliers.csv','materials':'data/raw/master/materials.csv','work_orders':'data/raw/erp/work_orders.csv','production_runs':'data/raw/mes/production_runs.csv','downtime_events':'data/raw/mes/downtime_events.csv','machine_telemetry':'data/raw/iot/machine_telemetry.csv','quality_inspections':'data/raw/quality/quality_inspections.csv','defect_events':'data/raw/quality/defect_events.csv','maintenance_orders':'data/raw/maintenance/maintenance_orders.csv','inventory_snapshots':'data/raw/inventory/inventory_snapshots.csv','supplier_receipts':'data/raw/inventory/supplier_receipts.csv','energy_usage':'data/raw/inventory/energy_usage.csv','machine_cdc':'data/raw/cdc/machine_cdc.csv','product_cdc':'data/raw/cdc/product_cdc.csv','calendar':'data/raw/reference/calendar.csv'}
def raw(n): return read_csv(ROOT/RAW[n])
def bronze(n,df):
    x=df.copy(); x['_bronze_loaded_at_utc']=pd.Timestamp.utcnow().isoformat(); x['_source_file']=RAW[n]; write_csv(x,BRONZE/f'{n}.csv')
def silver(n,df): write_csv(df,SILVER/f'{n}.csv')
def gold(n,df): write_csv(df,GOLD/f'{n}.csv')
def quarantine(n,df,reason):
    x=df.copy(); x['quarantine_reason']=reason
    if len(x)==0: x=pd.DataFrame(columns=['quarantine_reason'])
    write_csv(x,Q/f'{n}.csv')

def c_plants(x):
    x=x.copy(); x['plant_id']=clean_text(x['plant_id'],'','upper'); x['plant_name']=clean_text(x['plant_name'],case='title'); x['state']=clean_text(x['state'],'','upper'); x['region']=clean_text(x['region'],case='title'); x['open_date']=parse_date(x['open_date']); x['rated_daily_capacity_units']=parse_num(x['rated_daily_capacity_units'],0); x['active_flag']=parse_bool(x['active_flag']); return x.drop_duplicates('plant_id')
def c_lines(x):
    x=x.copy(); x['line_id']=clean_text(x['line_id'],'','upper'); x['plant_id']=clean_text(x['plant_id'],'','upper'); x['line_name']=clean_text(x['line_name'],case='title'); x['line_type']=clean_text(x['line_type'],case='title'); x['rated_units_per_hour']=parse_num(x['rated_units_per_hour'],0); x['commission_date']=parse_date(x['commission_date']); x['active_flag']=parse_bool(x['active_flag']); return x.drop_duplicates('line_id')
def c_machines(x):
    x=x.copy(); x['machine_id']=clean_text(x['machine_id'],'','upper'); x['line_id']=clean_text(x['line_id'],'','upper'); x['machine_name']=clean_text(x['machine_name'],case='title'); x['machine_type']=clean_text(x['machine_type'],case='upper'); x['manufacturer']=clean_text(x['manufacturer'],case='title'); x['install_date']=parse_date(x['install_date']); x['rated_power_kw']=parse_num(x['rated_power_kw']); x['machine_status']=clean_text(x['machine_status'],case='title'); x['criticality']=clean_text(x['criticality'],case='title'); return x.drop_duplicates('machine_id')
def c_products(x):
    x=x.copy(); x['product_id']=clean_text(x['product_id'],'','upper'); x['product_name']=clean_text(x['product_name'],case='title'); x['product_family']=clean_text(x['product_family'],case='title'); x['standard_cycle_time_sec']=parse_num(x['standard_cycle_time_sec']); x['standard_cost']=parse_num(x['standard_cost']); x['list_price']=parse_num(x['list_price']); x['active_flag']=parse_bool(x['active_flag']); return x.drop_duplicates('product_id')
def c_suppliers(x):
    x=x.copy(); x['supplier_id']=clean_text(x['supplier_id'],'','upper'); x['supplier_name']=clean_text(x['supplier_name'],case='title'); x['country']=clean_text(x['country'],'','upper'); x['supplier_tier']=clean_text(x['supplier_tier'],case='title'); x['lead_time_days']=parse_num(x['lead_time_days']); x['on_time_rate']=parse_num(x['on_time_rate']); x['quality_ppm']=parse_num(x['quality_ppm']); x['active_flag']=parse_bool(x['active_flag']); return x.drop_duplicates('supplier_id')
def c_materials(x):
    x=x.copy(); x['material_id']=clean_text(x['material_id'],'','upper'); x['material_name']=clean_text(x['material_name'],case='title'); x['material_category']=clean_text(x['material_category'],case='title'); x['supplier_id']=clean_text(x['supplier_id'],'','upper'); x['standard_cost']=parse_num(x['standard_cost']); x['safety_stock_qty']=parse_num(x['safety_stock_qty'],0); return x.drop_duplicates('material_id')
def c_work_orders(x):
    x=x.copy(); x['work_order_id']=clean_text(x['work_order_id'],'','upper'); x['product_id']=clean_text(x['product_id'],'','upper'); x['plant_id']=clean_text(x['plant_id'],'','upper'); x['line_id']=clean_text(x['line_id'],'','upper'); x['planned_start_date']=parse_date(x['planned_start_date']); x['planned_end_date']=parse_date(x['planned_end_date']); x['planned_qty']=parse_num(x['planned_qty']); x['priority']=clean_text(x['priority'],case='title'); x['work_order_status']=clean_text(x['work_order_status'],case='title'); return x.drop_duplicates('work_order_id')
def c_runs(x):
    x=x.copy(); x['production_run_id']=clean_text(x['production_run_id'],'','upper'); x['work_order_id']=clean_text(x['work_order_id'],'','upper'); x['line_id']=clean_text(x['line_id'],'','upper'); x['product_id']=clean_text(x['product_id'],'','upper'); x['run_start_ts']=parse_ts(x['run_start_ts']); x['run_end_ts']=parse_ts(x['run_end_ts']); x['run_date']=x['run_start_ts'].dt.date.astype('string'); x['good_units']=parse_num(x['good_units']); x['scrap_units']=parse_num(x['scrap_units'],0); x['rework_units']=parse_num(x['rework_units'],0); x['run_status']=clean_text(x['run_status'],case='title'); x['runtime_hours']=(x['run_end_ts']-x['run_start_ts']).dt.total_seconds()/3600; return x.drop_duplicates('production_run_id')
def c_down(x):
    x=x.copy(); x['downtime_event_id']=clean_text(x['downtime_event_id'],'','upper'); x['machine_id']=clean_text(x['machine_id'],'','upper'); x['line_id']=clean_text(x['line_id'],'','upper'); x['event_start_ts']=parse_ts(x['event_start_ts']); x['event_end_ts']=parse_ts(x['event_end_ts']); x['event_date']=x['event_start_ts'].dt.date.astype('string'); x['downtime_reason']=clean_text(x['downtime_reason'],case='title'); x['planned_flag']=parse_bool(x['planned_flag']); x['reported_minutes']=parse_num(x['reported_minutes']); x['calculated_minutes']=(x['event_end_ts']-x['event_start_ts']).dt.total_seconds()/60; return x.drop_duplicates('downtime_event_id')
def c_tel(x):
    x=x.copy(); x['telemetry_id']=clean_text(x['telemetry_id'],'','upper'); x['machine_id']=clean_text(x['machine_id'],'','upper'); x['reading_ts']=parse_ts(x['reading_ts']); x['reading_date']=x['reading_ts'].dt.date.astype('string')
    for c in ['temperature_c','vibration_mm_s','power_kw','rpm','pressure_bar']: x[c]=parse_num(x[c])
    x['status_code']=clean_text(x['status_code'],case='upper'); x['temperature_alert']=x['temperature_c']>=CFG['temperature_alert_c']; x['vibration_alert']=x['vibration_mm_s']>=CFG['vibration_alert_mm_s']; x['anomaly_flag']=x['temperature_alert']|x['vibration_alert']|x['status_code'].isin(['WARNING','TRIP']); return x.drop_duplicates('telemetry_id')
def c_quality(x):
    x=x.copy(); x['inspection_id']=clean_text(x['inspection_id'],'','upper'); x['production_run_id']=clean_text(x['production_run_id'],'','upper'); x['product_id']=clean_text(x['product_id'],'','upper'); x['inspection_ts']=parse_ts(x['inspection_ts']); x['units_inspected']=parse_num(x['units_inspected']); x['defect_units']=parse_num(x['defect_units']); x['result']=clean_text(x['result'],case='title'); x['defect_rate']=safe_div(x['defect_units'].fillna(0),x['units_inspected'].fillna(0)); return x.drop_duplicates('inspection_id')
def c_defects(x):
    x=x.copy(); x['defect_id']=clean_text(x['defect_id'],'','upper'); x['inspection_id']=clean_text(x['inspection_id'],'','upper'); x['defect_code']=clean_text(x['defect_code'],'','upper'); x['severity']=clean_text(x['severity'],case='title'); x['defect_qty']=parse_num(x['defect_qty'],0); x['disposition']=clean_text(x['disposition'],case='title'); return x.drop_duplicates('defect_id')
def c_maint(x):
    x=x.copy(); x['maintenance_order_id']=clean_text(x['maintenance_order_id'],'','upper'); x['machine_id']=clean_text(x['machine_id'],'','upper'); x['created_date']=parse_date(x['created_date']); x['scheduled_date']=parse_date(x['scheduled_date']); x['completed_date']=parse_date(x['completed_date']); x['maintenance_type']=clean_text(x['maintenance_type'],case='title'); x['priority']=clean_text(x['priority'],case='title'); x['labor_hours']=parse_num(x['labor_hours']); x['parts_cost']=parse_num(x['parts_cost'],0); x['maintenance_status']=clean_text(x['maintenance_status'],case='title'); return x.drop_duplicates('maintenance_order_id')
def c_inv(x):
    x=x.copy(); x['snapshot_date']=parse_date(x['snapshot_date']); x['plant_id']=clean_text(x['plant_id'],'','upper'); x['material_id']=clean_text(x['material_id'],'','upper'); x['on_hand_qty']=parse_num(x['on_hand_qty']); x['reserved_qty']=parse_num(x['reserved_qty'],0); x['on_order_qty']=parse_num(x['on_order_qty'],0); x['inventory_status']=clean_text(x['inventory_status'],case='title'); x['available_qty']=x['on_hand_qty']-x['reserved_qty']; return x.drop_duplicates(['snapshot_date','plant_id','material_id'],keep='last')
def c_receipts(x):
    x=x.copy(); x['receipt_id']=clean_text(x['receipt_id'],'','upper'); x['supplier_id']=clean_text(x['supplier_id'],'','upper'); x['material_id']=clean_text(x['material_id'],'','upper'); x['plant_id']=clean_text(x['plant_id'],'','upper'); x['expected_date']=parse_date(x['expected_date']); x['receipt_date']=parse_date(x['receipt_date']); x['ordered_qty']=parse_num(x['ordered_qty']); x['received_qty']=parse_num(x['received_qty']); x['rejected_qty']=parse_num(x['rejected_qty'],0); x['inspection_status']=clean_text(x['inspection_status'],case='title'); x['fill_rate']=safe_div(x['received_qty'].fillna(0),x['ordered_qty'].fillna(0)); x['late_receipt_flag']=pd.to_datetime(x['receipt_date'],errors='coerce')>pd.to_datetime(x['expected_date'],errors='coerce'); return x.drop_duplicates('receipt_id')
def c_energy(x):
    x=x.copy(); x['usage_date']=parse_date(x['usage_date']); x['plant_id']=clean_text(x['plant_id'],'','upper')
    for c in ['electricity_kwh','natural_gas_mmbtu','renewable_kwh','energy_cost']:
        x[c]=parse_num(x[c])
    return x.drop_duplicates(['usage_date','plant_id'])
def c_mcdc(x):
    x=x.copy(); x['cdc_id']=clean_text(x['cdc_id'],'','upper'); x['machine_id']=clean_text(x['machine_id'],'','upper'); x['effective_ts']=parse_ts(x['effective_ts']); x['effective_date']=x['effective_ts'].dt.date.astype('string'); x['new_machine_status']=clean_text(x['new_machine_status'],case='title'); x['new_criticality']=clean_text(x['new_criticality'],case='title'); return x.drop_duplicates('cdc_id')
def c_pcdc(x):
    x=x.copy(); x['cdc_id']=clean_text(x['cdc_id'],'','upper'); x['product_id']=clean_text(x['product_id'],'','upper'); x['effective_ts']=parse_ts(x['effective_ts']); x['effective_date']=x['effective_ts'].dt.date.astype('string'); x['new_standard_cost']=parse_num(x['new_standard_cost']); x['new_active_flag']=parse_bool(x['new_active_flag']); return x.drop_duplicates('cdc_id')
def c_cal(x): x=x.copy(); x['calendar_date']=parse_date(x['calendar_date']); return x.drop_duplicates('date_key')
CLEAN={'plants':c_plants,'lines':c_lines,'machines':c_machines,'products':c_products,'suppliers':c_suppliers,'materials':c_materials,'work_orders':c_work_orders,'production_runs':c_runs,'downtime_events':c_down,'machine_telemetry':c_tel,'quality_inspections':c_quality,'defect_events':c_defects,'maintenance_orders':c_maint,'inventory_snapshots':c_inv,'supplier_receipts':c_receipts,'energy_usage':c_energy,'machine_cdc':c_mcdc,'product_cdc':c_pcdc,'calendar':c_cal}
def machine_scd(base,cdc):
    b=base.copy(); b['effective_start_date']=b['install_date'].fillna('1900-01-01'); b['source']='machine_master'
    u=cdc.merge(base.drop(columns=['machine_status','criticality']),on='machine_id',how='inner'); u['machine_status']=u['new_machine_status']; u['criticality']=u['new_criticality']; u['effective_start_date']=u['effective_date']; u['source']='machine_cdc'; u=u[b.columns]
    x=pd.concat([b,u],ignore_index=True); x['_d']=pd.to_datetime(x['effective_start_date'],errors='coerce'); x=x.sort_values(['machine_id','_d']); x['effective_end_date']=x.groupby('machine_id')['_d'].shift(-1).dt.date.astype('string').fillna('9999-12-31'); x['is_current']=x['effective_end_date'].eq('9999-12-31'); x['machine_sk']=[stable_hash(a,b,c) for a,b,c in zip(x['machine_id'],x['effective_start_date'],x['machine_status'])]; return x.drop(columns='_d')
def product_scd(base,cdc):
    b=base.copy(); b['effective_start_date']='2026-01-01'; b['source']='product_master'; u=cdc.merge(base.drop(columns=['standard_cost','active_flag']),on='product_id',how='inner'); u['standard_cost']=u['new_standard_cost']; u['active_flag']=u['new_active_flag']; u['effective_start_date']=u['effective_date']; u['source']='product_cdc'; u=u[b.columns]; x=pd.concat([b,u],ignore_index=True); x['_d']=pd.to_datetime(x['effective_start_date'],errors='coerce'); x=x.sort_values(['product_id','_d']); x['effective_end_date']=x.groupby('product_id')['_d'].shift(-1).dt.date.astype('string').fillna('9999-12-31'); x['is_current']=x['effective_end_date'].eq('9999-12-31'); x['product_sk']=[stable_hash(a,b,c) for a,b,c in zip(x['product_id'],x['effective_start_date'],x['standard_cost'])]; return x.drop(columns='_d')
def main():
    for d in [BRONZE,SILVER,Q,GOLD,REPORT,META]: d.mkdir(parents=True,exist_ok=True)
    data={}; rc={}
    for n in RAW:
        r=raw(n); rc[n]=len(r); bronze(n,r); data[n]=CLEAN[n](r); silver(n,data[n])
    plants,lines,machines,products,suppliers,materials=data['plants'],data['lines'],data['machines'],data['products'],data['suppliers'],data['materials']; wo,runs,down,tel=data['work_orders'],data['production_runs'],data['downtime_events'],data['machine_telemetry']; qi,defs,maint,inv,receipts,energy=data['quality_inspections'],data['defect_events'],data['maintenance_orders'],data['inventory_snapshots'],data['supplier_receipts'],data['energy_usage']
    qs={}
    def q(n,df,reason): quarantine(n,df,reason); qs[n]=len(df)
    q('lines_invalid_plant',lines[~lines['plant_id'].isin(plants['plant_id'])],'Missing plant'); q('machines_invalid_line',machines[~machines['line_id'].isin(lines['line_id'])],'Missing line'); q('materials_invalid_supplier',materials[~materials['supplier_id'].isin(suppliers['supplier_id'])],'Missing supplier'); q('work_orders_invalid_product',wo[~wo['product_id'].isin(products['product_id'])],'Missing product'); q('work_orders_invalid_line',wo[~wo['line_id'].isin(lines['line_id'])],'Missing line'); q('runs_invalid_work_order',runs[~runs['work_order_id'].isin(wo['work_order_id'])],'Missing work order'); q('runs_bad_values',runs[runs['good_units'].isna()|runs['run_start_ts'].isna()],'Bad production values'); q('downtime_invalid_machine',down[~down['machine_id'].isin(machines['machine_id'])],'Missing machine'); q('telemetry_invalid_machine',tel[~tel['machine_id'].isin(machines['machine_id'])],'Missing machine'); q('telemetry_bad_values',tel[tel['reading_ts'].isna()|tel['power_kw'].isna()],'Bad telemetry'); q('quality_invalid_run',qi[~qi['production_run_id'].isin(runs['production_run_id'])],'Missing run'); q('quality_bad_values',qi[qi['defect_units'].isna()],'Bad defects'); q('defects_invalid_inspection',defs[~defs['inspection_id'].isin(qi['inspection_id'])],'Missing inspection'); q('maintenance_invalid_machine',maint[~maint['machine_id'].isin(machines['machine_id'])],'Missing machine'); q('inventory_invalid_material',inv[~inv['material_id'].isin(materials['material_id'])],'Missing material'); q('inventory_bad_values',inv[inv['on_hand_qty'].isna()],'Bad inventory'); q('receipts_invalid_supplier',receipts[~receipts['supplier_id'].isin(suppliers['supplier_id'])],'Missing supplier'); q('receipts_invalid_material',receipts[~receipts['material_id'].isin(materials['material_id'])],'Missing material'); q('receipts_bad_values',receipts[receipts['received_qty'].isna()],'Bad receipt quantity')
    mscd=machine_scd(machines,data['machine_cdc']); pscd=product_scd(products,data['product_cdc']); gold('dim_machine_scd2',mscd); gold('dim_machine_current',mscd[mscd['is_current']]); gold('dim_product_scd2',pscd); gold('dim_product_current',pscd[pscd['is_current']])
    for n,df in {'dim_plant':plants,'dim_line':lines,'dim_supplier':suppliers,'dim_material':materials}.items(): gold(n,df)
    vr=runs[runs['work_order_id'].isin(wo['work_order_id'])&runs['product_id'].isin(products['product_id'])&runs['good_units'].notna()].copy(); vr['total_units']=vr['good_units']+vr['scrap_units']+vr['rework_units']; vr['scrap_rate']=safe_div(vr['scrap_units'],vr['total_units']); vr['rework_rate']=safe_div(vr['rework_units'],vr['total_units']); vr=vr.merge(products[['product_id','standard_cycle_time_sec','standard_cost']],on='product_id',how='left'); vr['ideal_runtime_hours']=vr['good_units']*vr['standard_cycle_time_sec']/3600; vr['performance_ratio']=np.minimum(1,safe_div(vr['ideal_runtime_hours'],vr['runtime_hours'])); gold('fact_production_runs',vr)
    vt=tel[tel['machine_id'].isin(machines['machine_id'])&tel['reading_ts'].notna()&tel['power_kw'].notna()].copy(); gold('fact_machine_telemetry',vt)
    vd=down[down['machine_id'].isin(machines['machine_id'])].copy(); vd['downtime_minutes']=vd['calculated_minutes'].fillna(vd['reported_minutes']); gold('fact_downtime',vd)
    vq=qi[qi['production_run_id'].isin(vr['production_run_id'])&qi['defect_units'].notna()].copy(); gold('fact_quality_inspections',vq); gold('fact_defects',defs[defs['inspection_id'].isin(vq['inspection_id'])])
    vm=maint[maint['machine_id'].isin(machines['machine_id'])].copy(); gold('fact_maintenance_orders',vm); gold('fact_supplier_receipts',receipts[receipts['supplier_id'].isin(suppliers['supplier_id'])&receipts['material_id'].isin(materials['material_id'])&receipts['received_qty'].notna()]); gold('fact_energy_usage',energy)
    prod_day=vr.groupby(['run_date','line_id'],as_index=False).agg(good_units=('good_units','sum'),scrap_units=('scrap_units','sum'),rework_units=('rework_units','sum'),runtime_hours=('runtime_hours','sum'),ideal_runtime_hours=('ideal_runtime_hours','sum'),run_count=('production_run_id','count')); prod_day['quality_ratio']=safe_div(prod_day['good_units'],prod_day['good_units']+prod_day['scrap_units']+prod_day['rework_units']); prod_day['performance_ratio']=np.minimum(1,safe_div(prod_day['ideal_runtime_hours'],prod_day['runtime_hours']))
    dt_day=vd.groupby(['event_date','line_id'],as_index=False).agg(downtime_minutes=('downtime_minutes','sum')); oee=prod_day.merge(dt_day,left_on=['run_date','line_id'],right_on=['event_date','line_id'],how='left').fillna({'downtime_minutes':0}); oee['scheduled_minutes']=oee['runtime_hours']*60+oee['downtime_minutes']; oee['availability']=safe_div(oee['runtime_hours']*60,oee['scheduled_minutes']); oee['oee']=oee['availability']*oee['performance_ratio']*oee['quality_ratio']; gold('mart_daily_line_oee',oee)
    machine_health=vt.groupby('machine_id',as_index=False).agg(readings=('telemetry_id','count'),avg_temp_c=('temperature_c','mean'),max_temp_c=('temperature_c','max'),avg_vibration=('vibration_mm_s','mean'),max_vibration=('vibration_mm_s','max'),avg_power_kw=('power_kw','mean'),anomaly_count=('anomaly_flag','sum'))
    dsum=vd.groupby('machine_id',as_index=False).agg(failure_events=('downtime_event_id','count'),downtime_minutes=('downtime_minutes','sum')); machine_health=machines.merge(machine_health,on='machine_id',how='left').merge(dsum,on='machine_id',how='left').fillna({'readings':0,'anomaly_count':0,'failure_events':0,'downtime_minutes':0}); machine_health['anomaly_rate']=safe_div(machine_health['anomaly_count'],machine_health['readings']); machine_health['mttr_hours']=safe_div(machine_health['downtime_minutes']/60,machine_health['failure_events']); machine_health['health_score']=100-(machine_health['anomaly_rate']*100).clip(upper=50)-(machine_health['failure_events']*2).clip(upper=30); gold('mart_machine_health',machine_health.sort_values('health_score'))
    reliability=machine_health[['machine_id','failure_events','downtime_minutes','mttr_hours']].copy(); telemetry_hours=vt.groupby('machine_id',as_index=False).agg(observed_hours=('telemetry_id','count')); reliability=reliability.merge(telemetry_hours,on='machine_id',how='left'); reliability['mtbf_hours']=safe_div(reliability['observed_hours'],reliability['failure_events']); gold('mart_machine_reliability',reliability.sort_values('mtbf_hours'))
    quality_mart=vq.groupby('product_id',as_index=False).agg(inspections=('inspection_id','count'),units_inspected=('units_inspected','sum'),defect_units=('defect_units','sum')); quality_mart['defect_rate']=safe_div(quality_mart['defect_units'],quality_mart['units_inspected']); quality_mart=quality_mart.merge(products[['product_id','product_name','product_family']],on='product_id',how='left'); gold('mart_product_quality',quality_mart.sort_values('defect_rate',ascending=False))
